    TransferData *transfer_data = (TransferData *)data;
    Connection *connection = transfer_data->connection;
    Buddy *buddy = connection->buddy;

    // Start the file transfer
    FileTransfer *file_transfer = start_file_transfer(transfer_data->file_info, buddy);

    if (!file_transfer) {
        return FALSE;
    }

    // Set up various callbacks for the transfer
    setup_transfer_callbacks(file_transfer);

    // Associate transfer data with the file transfer object
    file_transfer->user_data = transfer_data;

    return FALSE;
}

gboolean handle_file_transfer_initiation(gpointer data, gint fd, b_input_condition cond) {
    TransferData *transfer_data = (TransferData *)data;
    Transfer *transfer = transfer_data->transfer;
    Connection *connection = transfer_data->connection;
    Buddy *buddy = buddy_find(transfer->buddy_handle);

    if (!buddy || !transfer || !connection) {
        return FALSE;
    }

    if (!file_transfer_start(transfer, connection, buddy)) {
        return FALSE;
    }

    transfer->callbacks.on_data = transfer_data_handler;
    transfer->callbacks.on_complete = transfer_complete_handler;
    transfer->callbacks.on_error = transfer_error_handler;

    file_transfer_set_data(transfer, transfer_data);

    return FALSE;
}

gboolean handle_file_transfer_initiation(gpointer data, gint fd, b_input_condition cond) {
    TransferData *transfer_data = (TransferData *)data;
    Transfer *transfer = transfer_data->transfer;
    Connection *connection = transfer_data->connection;
    Buddy *buddy = get_buddy_by_id(connection, transfer->buddy_id);

    if (!buddy) {
        return FALSE;
    }

    if (!start_file_transfer(transfer, buddy)) {
        return FALSE;
    }

    setup_transfer_callbacks(transfer);
    associate_transfer_data_with_object(transfer, transfer_data);

    return FALSE;
}

gboolean handle_new_file_transfer(gpointer data, gint fd, b_input_condition cond) {
    TransferData *transfer_data = (TransferData *)data;
    Connection *connection = transfer_data->connection;
    Buddy *buddy = connection_find_buddy(connection, transfer_data->buddy_id);

    if (!buddy) {
        return FALSE;
    }

    FileTransfer *file_transfer = file_transfer_new();
    file_transfer->data = transfer_data;
    file_transfer->buddy = buddy;
    file_transfer->fd = fd;

    g_signal_connect(file_transfer, "started", G_CALLBACK(on_file_transfer_started), NULL);
    g_signal_connect(file_transfer, "completed", G_CALLBACK(on_file_transfer_completed), NULL);
    g_signal_connect(file_transfer, "error", G_CALLBACK(on_file_transfer_error), NULL);

    start_file_transfer(file_transfer);

    return FALSE;
}
